{"content": "1|/**
2| * FairFahren — entry point. Wires world generation, physics, rendering and input.
3| *
4| *   generateCity(seed) ──► city data ──► buildCityMesh ──► GPU (static)
5| *                               │
6| *   Keyboard ──► stepCar ──► collideCar(city.colliders) ──► Camera ──► Renderer
7| */
8|import { generateCity, streetAt } from './world/cityGen.js';
9|import { buildCityMesh } from './world/cityMesh.js';
10|import { TAXI, createCar, stepCar } from './vehicle/carPhysics.js';
11|import { collideCar } from './vehicle/collision.js';
12|import { buildTaxi, wheelOffsets } from './vehicle/taxiModel.js';
13|import { Renderer } from './gfx/renderer.js';
14|import { Keyboard } from './game/input.js';
15|import { Camera } from './game/camera.js';
16|import { Hud } from './game/hud.js';
17|import { compose, translation, rotationX, rotationY } from './core/math.js';
18|
19|const PHYSICS_STEP = 1 / 120; // fixed timestep keeps physics deterministic
20|const ENV = {
21|  sunDir: normalize([0.35, 0.8, 0.5]),
22|  fogColor: [0.75, 0.79, 0.84], // hazy Berlin sky
23|  fogDensity: 0.0016,
24|  time: 0,
25|};
26|
27|const seedParam = Number.parseInt(new URLSearchParams(location.search).get('seed') ?? '', 10);
28|const city = generateCity(Number.isFinite(seedParam) ? { seed: seedParam } : {});
29|
30|let renderer;
31|try {
32|  renderer = new Renderer(document.querySelector('canvas'));
33|} catch (err) {
34|  document.querySelector('#error').textContent = err.message;
35|  throw err;
36|}
37|
38|const cityMesh = renderer.upload(buildCityMesh(city));
39|const taxiParts = buildTaxi(TAXI);
40|const taxi = { body: renderer.upload(taxiParts.body), wheel: renderer.upload(taxiParts.wheel), shadow: renderer.upload(taxiParts.shadow) };
41|const wheels = wheelOffsets(TAXI);
42|
43|const car = createCar(city.spawn);
44|const keyboard = new Keyboard(window);
45|const camera = new Camera();
46|const hud = new Hud(document);
47|hud.set('seed', `Seed ${city.seed}`);
48|
49|// Handy for debugging in the browser console and for automated checks.
50|window.fairfahren = { city, car, camera, TAXI };
51|
52|let last = performance.now(), accumulator = 0, fps = 60;
53|
54|function frame(now) {
55|  const dt = Math.min((now - last) / 1000, 0.1);
56|  last = now;
57|  ENV.time += dt;
58|
59|  if (keyboard.consume('KeyR')) {
60|    Object.assign(car, createCar(city.spawn));
61|    camera.snap();
62|  }
63|  if (keyboard.consume('KeyC')) camera.next();
64|
65|  const input = keyboard.driving();
66|  for (accumulator += dt; accumulator >= PHYSICS_STEP; accumulator -= PHYSICS_STEP) {
67|    stepCar(car, input, TAXI, PHYSICS_STEP);
68|    collideCar(car, city.colliders, TAXI);
69|  }
70|  camera.update(car, dt);
71|
72|  renderer.beginFrame(camera.matrices(renderer.resize()), ENV);
73|  renderer.draw(cityMesh);
74|  const carMatrix = compose(translation(car.x, 0, car.z), rotationY(car.heading));
75|  renderer.draw(taxi.body, carMatrix);
76|  for (const w of wheels) {
77|    const steer = rotationY(w.front ? car.steer : 0);
78|    renderer.draw(taxi.wheel, compose(carMatrix, translation(w.x, w.y, w.z), steer, rotationX(car.wheelSpin)));
79|  }
80|  renderer.draw(taxi.shadow, carMatrix, true);
81|
82|  fps += (1 / Math.max(dt, 1e-3) - fps) * 0.05;
83|  hud.set('speed', String(Math.round(Math.abs(car.speed) * 3.6)));
84|  hud.set('street', streetAt(city, car.x, car.z));
85|  hud.set('fps', `${Math.round(fps)} fps · ${camera.modeName} cam`);
86|  keyboard.endFrame();
87|  requestAnimationFrame(frame);
88|}
89|requestAnimationFrame(frame);
90|
91|function normalize(v) {
92|  const l = Math.hypot(...v);
93|  return v.map((c) => c / l);
