{"content": "1|/**
2| * Arcade car physics using a kinematic bicycle model.
3| * PURE: no DOM, no WebGL — runs in Node for tests.
4| *
5| * Car state: position (x, z), heading (rad, 0 = facing +Z / south), speed (m/s,
6| * negative when reversing), steer (front wheel angle in rad, + = left).
7| */
8|import { approach } from '../core/math.js';
9|
10|/** Tuning for a typical German taxi (mid-size saloon). */
11|export const TAXI = {
12|  wheelBase: 2.9, // m between axles
13|  trackWidth: 1.64, // m between left and right wheels
14|  wheelRadius: 0.34,
15|  maxSteer: 0.6, // rad at standstill
16|  steerRate: 2.5, // rad/s the steering wheel can turn
17|  maxLateralAccel: 14, // m/s² — arcade grip (a real saloon manages ~9)
18|  engineAccel: 6.5, // m/s² at standstill, fades out towards maxSpeed
19|  brakeDecel: 14,
20|  reverseAccel: 4,
21|  maxSpeed: 36, // m/s ≈ 130 km/h
22|  maxReverse: 8,
23|  rollingResistance: 0.4, // m/s²
24|  airDrag: 0.0022, // m/s² per (m/s)²
25|  handbrakeDecel: 9,
26|  collisionRadius: 0.95, // the body is approximated by two circles
27|  collisionOffset: 1.45, // their distance from the centre along the car axis
28|  restitution: 0.25, // bounce on impact
29|};
30|
31|export function createCar({ x, z, heading }) {
32|  return { x, z, heading, speed: 0, steer: 0, wheelSpin: 0 };
33|}
34|
35|/**
36| * Advances the car by dt seconds.
37| * input = { throttle: 0..1, brake: 0..1, steer: -1..1 (+ = left), handbrake: bool }
38| */
39|export function stepCar(car, input, spec, dt) {
40|  // Grip-limited steering: never ask the tyres for more than maxLateralAccel (v²/L·tan δ ≤ a).
41|  const steerLimit = Math.min(spec.maxSteer, Math.atan((spec.maxLateralAccel * spec.wheelBase) / (car.speed * car.speed + 1e-6)));
42|  car.steer = approach(car.steer, input.steer * steerLimit, spec.steerRate * dt);
43|
44|  // Throttle accelerates forward (or brakes while rolling backwards), brake does the opposite.
45|  const v = car.speed;
46|  let accel = 0;
47|  if (input.throttle) accel += v < -0.5 ? spec.brakeDecel : input.throttle * spec.engineAccel * (1 - Math.max(v, 0) / spec.maxSpeed);
48|  if (input.brake) accel -= v > 0.5 ? spec.brakeDecel : input.brake * spec.reverseAccel * (1 + Math.min(v, 0) / spec.maxReverse);
49|  car.speed += accel * dt;
50|
51|  // Resistances oppose motion but never reverse it on their own.
52|  let drag = spec.rollingResistance + spec.airDrag * car.speed * car.speed;
53|  if (input.handbrake) drag += spec.handbrakeDecel;
54|  car.speed -= Math.sign(car.speed) * Math.min(Math.abs(car.speed), drag * dt);
55|
56|  // Bicycle model: yaw rate follows from speed, wheel base and steering angle.
57|  const yawRate = (car.speed / spec.wheelBase) * Math.tan(car.steer) * (input.handbrake ? 1.4 : 1);
58|  car.heading += yawRate * dt;
59|  car.x += Math.sin(car.heading) * car.speed * dt;
60|  car.z += Math.cos(car.heading) * car.speed * dt;
61|  car.wheelSpin = (car.wheelSpin + (car.speed / spec.wheelRadius) * dt) % (Math.PI * 2);
62|  return car;
63|}", "total_lines": 63, "file_size": 2853, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

