{"content": "1|import { VERTEX_SHADER, FRAGMENT_SHADER } from './shaders.js';
2|import { FLOATS_PER_VERTEX } from './meshBuilder.js';
3|import { identity } from '../core/math.js';
4|
5|const UNIFORMS = ['uProj', 'uView', 'uModel', 'uEye', 'uSunDir', 'uFogColor', 'uFogDensity', 'uTime'];
6|
7|/** Thin WebGL2 wrapper: one program, static meshes, one draw call per mesh. */
8|export class Renderer {
9|  constructor(canvas) {
10|    const gl = canvas.getContext('webgl2', { antialias: true });
11|    if (!gl) throw new Error('WebGL2 is not available in this browser.');
12|    this.gl = gl;
13|    this.canvas = canvas;
14|    this.program = createProgram(gl, VERTEX_SHADER, FRAGMENT_SHADER);
15|    this.u = Object.fromEntries(UNIFORMS.map((name) => [name, gl.getUniformLocation(this.program, name)]));
16|    gl.enable(gl.DEPTH_TEST);
17|    gl.enable(gl.CULL_FACE);
18|    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
19|  }
20|
21|  /** Uploads a MeshBuilder to the GPU. Returns a handle for draw(). */
22|  upload(builder) {
23|    const gl = this.gl;
24|    const vao = gl.createVertexArray();
25|    gl.bindVertexArray(vao);
26|    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
27|    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(builder.vertices), gl.STATIC_DRAW);
28|    const stride = FLOATS_PER_VERTEX * 4;
29|    [3, 3, 3, 1].reduce((offset, size, loc) => {
30|      gl.enableVertexAttribArray(loc);
31|      gl.vertexAttribPointer(loc, size, gl.FLOAT, false, stride, offset * 4);
32|      return offset + size;
33|    }, 0);
34|    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, gl.createBuffer());
35|    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint32Array(builder.indices), gl.STATIC_DRAW);
36|    gl.bindVertexArray(null);
37|    return { vao, count: builder.indices.length };
38|  }
39|
40|  /** Matches the drawing buffer to the CSS size. Returns the aspect ratio. */
41|  resize() {
42|    const dpr = Math.min(window.devicePixelRatio || 1, 2);
43|    const w = Math.round(this.canvas.clientWidth * dpr), h = Math.round(this.canvas.clientHeight * dpr);
44|    if (this.canvas.width !== w || this.canvas.height !== h) {
45|      this.canvas.width = w;
46|      this.canvas.height = h;
47|    }
48|    this.gl.viewport(0, 0, w, h);
49|    return w / Math.max(h, 1);
50|  }
51|
52|  /** view = { proj, view, eye }, env = { sunDir, fogColor, fogDensity, time } */
53|  beginFrame(view, env) {
54|    const gl = this.gl, u = this.u;
55|    gl.clearColor(...env.fogColor, 1);
56|    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
57|    gl.useProgram(this.program);
58|    gl.uniformMatrix4fv(u.uProj, false, view.proj);
59|    gl.uniformMatrix4fv(u.uView, false, view.view);
60|    gl.uniform3fv(u.uEye, view.eye);
61|    gl.uniform3fv(u.uSunDir, env.sunDir);
62|    gl.uniform3fv(u.uFogColor, env.fogColor);
63|    gl.uniform1f(u.uFogDensity, env.fogDensity);
64|    gl.uniform1f(u.uTime, env.time);
65|  }
66|
67|  draw(mesh, model = identity(), transparent = false) {
68|    const gl = this.gl;
69|    if (transparent) {
70|      gl.enable(gl.BLEND);
71|      gl.depthMask(false);
72|    }
73|    gl.uniformMatrix4fv(this.u.uModel, false, model);
74|    gl.bindVertexArray(mesh.vao);
75|    gl.drawElements(gl.TRIANGLES, mesh.count, gl.UNSIGNED_INT, 0);
76|    if (transparent) {
77|      gl.disable(gl.BLEND);
78|      gl.depthMask(true);
79|    }
80|  }
81|}
82|
83|function createProgram(gl, vsSource, fsSource) {
84|  const compile = (type, src) => {
85|    const s = gl.createShader(type);
86|    gl.shaderSource(s, src);
87|    gl.compileShader(s);
88|    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s));
89|    return s;
90|  };
91|  const p = gl.createProgram();
92|  gl.attachShader(p, compile(gl.VERTEX_SHADER, vsSource));
93|  gl.attachShader(p, compile(gl.FRAGMENT_SHADER, fsSource));
94|  gl.linkProgram(p);
95|  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(p));
96|  return p;
