{"content": "1|/**
2| * Builds triangle meshes on the CPU from primitive shapes.
3| *
4| * Every vertex carries: position(3) normal(3) color(3) material(1).
5| * The material id tells the fragment shader which procedural pattern to paint
6| * (windows, water, asphalt ...), so no textures are needed.
7| *
8| * Shapes are flat-shaded (one normal per face) for a clean low-poly look.
9| * Faces are oriented automatically: pass a point that lies inside the solid
10| * and the face will point away from it (correct normal + CCW winding).
11| */
12|
13|export const FLOATS_PER_VERTEX = 10;
14|
15|export const MAT = {
16|  PLAIN: 0,
17|  ALTBAU: 1, // pre-war facade: tall windows, shop fronts on the ground floor
18|  PLATTE: 2, // prefab panel building: panel joints, dense window grid
19|  WATER: 3,
20|  ASPHALT: 4,
21|  PAINT: 5, // glossy (car paint, glass, metal)
22|  SHADOW: 6, // soft blob shadow, color.xy carries the uv
23|};
24|
25|/** 0xRRGGBB -> [r, g, b] in 0..1 */
26|export const rgb = (hex) => [((hex >> 16) & 255) / 255, ((hex >> 8) & 255) / 255, (hex & 255) / 255];
27|
28|export class MeshBuilder {
29|  constructor() {
30|    this.vertices = [];
31|    this.indices = [];
32|  }
33|
34|  get vertexCount() {
35|    return this.vertices.length / FLOATS_PER_VERTEX;
36|  }
37|
38|  /** Convex planar polygon. `inside` is a point the normal should point away from. */
39|  poly(pts, color, mat = MAT.PLAIN, inside = null) {
40|    // Newell's method: robust normal for any planar polygon.
41|    let nx = 0, ny = 0, nz = 0, cx = 0, cy = 0, cz = 0;
42|    for (let i = 0; i < pts.length; i++) {
43|      const a = pts[i], b = pts[(i + 1) % pts.length];
44|      nx += (a[1] - b[1]) * (a[2] + b[2]);
45|      ny += (a[2] - b[2]) * (a[0] + b[0]);
46|      nz += (a[0] - b[0]) * (a[1] + b[1]);
47|      cx += a[0]; cy += a[1]; cz += a[2];
48|    }
49|    const len = Math.hypot(nx, ny, nz);
50|    if (len < 1e-9) return; // degenerate
51|    nx /= len; ny /= len; nz /= len;
52|    if (inside) {
53|      const n = pts.length;
54|      const dot = nx * (cx / n - inside[0]) + ny * (cy / n - inside[1]) + nz * (cz / n - inside[2]);
55|      if (dot < 0) {
56|        pts = pts.slice().reverse();
57|        nx = -nx; ny = -ny; nz = -nz;
58|      }
59|    }
60|    const base = this.vertexCount;
61|    for (const p of pts) this.vertices.push(p[0], p[1], p[2], nx, ny, nz, color[0], color[1], color[2], mat);
62|    for (let i = 1; i < pts.length - 1; i++) this.indices.push(base, base + i, base + i + 1);
63|  }
64|
65|  /** Horizontal rectangle facing up. */
66|  rect(x0, z0, x1, z1, y, color, mat = MAT.PLAIN) {
67|    this.poly([[x0, y, z0], [x1, y, z0], [x1, y, z1], [x0, y, z1]], color, mat, [x0, y - 1, z0]);
68|  }
69|
70|  /** Axis-aligned box. opts: { mat, top (color), topMat, bottom (bool) } */
71|  box(x0, y0, z0, x1, y1, z1, color, opts = {}) {
72|    const mat = opts.mat ?? MAT.PLAIN;
73|    const c = [(x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2];
74|    this.poly([[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0]], color, mat, c);
75|    this.poly([[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]], color, mat, c);
76|    this.poly([[x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0]], color, mat, c);
77|    this.poly([[x1, y0, z0], [x1, y0, z1], [x1, y1, z1], [x1, y1, z0]], color, mat, c);
78|    this.poly([[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]], opts.top ?? color, opts.topMat ?? mat, c);
79|    if (opts.bottom) this.poly([[x0, y0, z0], [x1, y0, z0], [x1, y0, z1], [x0, y0, z1]], color, mat, c);
80|  }
81|
82|  /** Vertical cone stump around (cx, cz). r1 === r0 gives a cylinder, r1 === 0 a cone. */
83|  frustum(cx, y0, cz, r0, y1, r1, segs, color, mat = MAT.PLAIN) {
84|    const inside = [cx, (y0 + y1) / 2, cz];
85|    const ring = (r, y) => Array.from({ length: segs }, (_, i) => {
86|      const a = (i / segs) * Math.PI * 2;
87|      return [cx + Math.cos(a) * r, y, cz + Math.sin(a) * r];
88|    });
