143|/** The server's seed wins: regenerate city + static mesh synchronously (~1 ms). */
144|function rebuildWorld(seed) {
145|  if (seed === null || seed === city.seed) return;
146|  city = generateCity({ seed });
147|  window.fairfahren.city = city;
148|  cityMesh = renderer.upload(buildCityMesh(city));
