153|function onRoster(players) {
154|  // Our own id: we receive rosters only once OUR join is in (the server
155|  // subscribes us first), and we sit last in join order in that first one.
156|  if (selfId === null && players.length) selfId = players[players.length - 1].id;
157|  ui.roster.innerHTML = players.map((p, i) =>
158|    `<li><span class="dot" style="background:${cssColor(i)}"></span>${escapeHtml(p.name)}</li>`).join('');
159|}
