161|/** One seed/player-count step: rebuild the pure track + the ampel scenery. */
162|function ensureTrack(n) {
163|  const want = `${city.seed}/${n}`;
164|  if (track && trackFor === want) return;
165|  if (!Number.isInteger(n) || n < 2 || n > 4) return;
166|  try {
167|    track = buildTrack(city, n);
168|    trackFor = want;
169|    buildScenery();
170|  } catch (err) { console.error('track:', err.message); }
171|}
172|
173|/** Per race stage change: grid placement, freeze gate, bookkeeping resets. */
174|function onStage(s) {
175|  if (s === 'countdown') {
176|    remotes.clear(); jumps.clear();
177|    otherFinishes = []; ownT = null; myFinish = null; prevCross = null;
178|    results = null; podium = null; gridded = false;
179|    ui.results.hidden = true;
180|    ui.againBtn.hidden = true;
181|    ensureTrack(net.players.length);
182|    gridSelf();
183|    gate = createStartGate({
184|      isGreen: () => net.stage === 'racing' || net.stage === 'finished',
185|      onJump: () => net.sendRaw(encode('jump', {})), // the gate fires once; server settles
186|    });
187|  }
188|  if (s === 'racing') prevCross = null; // crossing maths starts at green
189|  if (s === 'ceremony') setPodium();
190|}
191|
192|/** Place the local car on our roster-position grid slot, camera snapped. */
193|function gridSelf() {
194|  const i = Math.max(0, net.players.findIndex((p) => p.id === selfId));
195|  const slot = track?.grid[Math.min(i, (track?.grid.length ?? 1) - 1)];
196|  if (slot) { gridded = true; Object.assign(car, createCar(slot)); camera.snap(); }
197|}
