199|/** Ampel for the current track: dark pole + housing, one lit-lamp mesh per state. */
200|function buildScenery() {
201|  const a = track.ampel, dark = rgb(0x24282e);
202|  const base = new MeshBuilder();
203|  base.box(a.x - 0.14, 0, a.z - 0.14, a.x + 0.14, 2.7, a.z + 0.14, dark, { mat: MAT.PAINT });
204|  base.box(a.x - 0.3, 2.7, a.z - 0.18, a.x + 0.3, 3.75, a.z + 0.18, dark, { mat: MAT.PAINT });
205|  for (const y of [2.78, 3.06, 3.34]) base.box(a.x - 0.12, y, a.z + 0.18, a.x + 0.12, y + 0.22, a.z + 0.21, rgb(0x14161a));
206|  const lit = { red: 0xe02020, amber: 0xf5a000, green: 0x22cc44 };
207|  const on = { red: ['red'], 'red+amber': ['red', 'amber'], green: ['green'] };
208|  const yOf = { green: 2.78, amber: 3.06, red: 3.34 };
209|  ampel = {
210|    base: renderer.upload(base),
211|    lamp: Object.fromEntries(Object.entries(on).map(([state, names]) => {
212|      const b = new MeshBuilder();
213|      for (const n of names) {
214|        const y = yOf[n];
215|        b.box(a.x - 0.12, y, a.z + 0.18, a.x + 0.12, y + 0.22, a.z + 0.23, rgb(lit[n]), { mat: MAT.PAINT });
216|      }
217|      return [state, renderer.upload(b)];
218|    })),
219|  };
