303|/** Live position: settled order once results are in, else crossed-before count. */
304|function posText(st) {
305|  if (results) {
306|    const i = results.findIndex((r) => r.id === selfId);
307|    return i >= 0 ? `P${i + 1}` : '';
308|  }
