313|/** The online loop: the solo renderer, with the race state machine around it. */
314|function onlineFrame(now, dt) {
315|  const st = net.stage;
316|  updateLobby();
317|  ensureTrack(net.players.length);
318|  const sNow = net.clock.serverNow(performance.now());
319|  const light = goAt !== null && sNow !== null ? ampelState(sNow, goAt) : null;
320|
321|  if (keyboard.consume('KeyC')) camera.next();
322|  if (keyboard.consume('KeyR')) { // respawn stays: back to our slot once we have one
323|    if (track && gridded) gridSelf();
324|    else { Object.assign(car, createCar(city.spawn)); camera.snap(); }
325|  }
326|
327|  // Local physics from the grid on, behind the pure freeze gate; through the
328|  // whole lobby the taxi is parked, hidden and never stepped.
329|  const input = keyboard.driving();
330|  if (gate && st !== 'lobby' && st !== 'ceremony') {
331|    for (accumulator += dt; accumulator >= PHYSICS_STEP; accumulator -= PHYSICS_STEP) {
332|      gate.step(car, input, TAXI, PHYSICS_STEP);
333|      collideCar(car, city.colliders, TAXI);
334|      // ms-precise finish crossing, reported once as master-clock time T.
335|      if (track && st === 'racing' && myFinish === null) {
336|        const cur = { x: car.x, t: performance.now() };
337|        if (prevCross) {
338|          const cross = crossingTime(prevCross, cur, track.finish.x);
339|          if (cross !== null) {
340|            myFinish = cross;
341|            net.sendFinish(net.clock.serverNow(cross) ?? performance.now()); // unsynced → local now
342|          }
343|        }
344|        prevCross = cur;
345|      }
346|    }
347|    if (now - lastPos >= 66) { // stream our state at ~15 Hz
348|      lastPos = now;
349|      net.sendPos({ x: car.x, z: car.z, h: car.heading, s: car.speed });
350|    }
351|  } else accumulator = 0;
352|
353|  // Camera: normal rigs while driving, a dedicated orbit over the podium.
354|  const aspect = renderer.resize();
355|  let view;
356|  if (st === 'ceremony' && podium) {
357|    orbit += dt * 0.35;
358|    const [cx, cz] = podium.center;
359|    const eye = [cx + Math.cos(orbit) * 14, 6, cz + Math.sin(orbit) * 14];
360|    view = { proj: perspective(1.0, aspect, 0.5, 1500), view: lookAt(eye, [cx, 0.6, cz]), eye };
361|  } else {
362|    camera.update(car, dt);
363|    view = camera.matrices(aspect);
364|  }
365|
366|  renderer.beginFrame(view, ENV);
367|  renderer.draw(cityMesh);
368|  if (ampel) {
369|    renderer.draw(ampel.base);
370|    if (light) renderer.draw(ampel.lamp[light]); // only the active lamp mesh
371|  }
372|
373|  for (const [id, r] of remotes) { // ghosts run ~100 ms behind the render clock
374|    const s = r.interp.sample(now);
375|    if (s) {
376|      r.spin = (r.spin + s.s * dt / TAXI.wheelRadius) % (Math.PI * 2);
377|      drawCar(s.x, s.z, s.h, colorIndex(id), r.spin, 0);
378|    }
